Here is a simple implementation of the Binary Search algorithm in C++:

```cpp
#include <iostream>
using namespace std;

int binarySearch(int arr[], int n, int target) {
    int left = 0;
    int right = n - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (arr[mid] == target)
            return mid;

        else if (arr[mid] > target)
            right = mid - 1;

        else
            left = mid + 1;
    }

    return -1; // Return -1 if element is not found
}

int main() {
    int arr[] = {2, 3, 4, 10, 40};
    int n = sizeof(arr)/sizeof(arr[0]);
    int target = 10;

    int result = binarySearch(arr, n, target);

    if(result != -1){
        cout << "Element found at index " << result << endl;
    }
    else{
        cout << "Element not found in array" << endl;
    }

    return 0;
}
```

This program defines a function `binarySearch` that takes an array of integers and its size as well as the value to be searched. It returns the index of the element when it is found or `-1` otherwise.

The main part of the code creates an example array, specifies the target number to search for (`10`), calls the `binarySearch` function with these parameters, and prints out whether the target was found and where (if found).
